const commands = {
  'reserve-stock': (p) => stock.reserve(p.orderId, p.qty),
  'cancel-order': (p) => stock.cancel(p.orderId),
};

function handle(message) {
  const run = commands[message.type];
  if (!run) throw new Error(`unknown command: ${message.type}`);
  return run(message.payload);
}
